            <!-- INSTRUCTION BOX -->
            <div class="citation" style="background-color: #f8f9fa;">
<p>This errata page started after the publication of the Second Edition of the <em>The Jepson Manual</em> (2012).
</p>
<p>The goal of the Errata page is to provide documentation of small corrections to treatments presented in both the print book (TJM2, 2012) and the Jepson eFlora. 
</p>
<p>Format example<br>
Taxon name<br>
Current Jepson eFlora text<br>
<span style="color: #0058a3; font-weight: bold;">Describes the change made (from either TJM2 or the eFlora)</span><br>

<p>Entries are listed alphabetically. They can also be shown by date of correction.
</p>
<p>The Jepson eFlora is revised annually to include substantive taxonomic changes (e.g., taxa added or deleted) that are informed by the most recent scientific evidence. Strictly nomenclatural changes are made as errata throughout the year and summarized in that year’s revision. Click here to see a full list of Jepson eFlora revisions. 
</p>
