        THINGS TO REMEMBER WHEN USING THIS BOOK — Assumptions</p>
        <span class="erratum-detail">'Also, unless stated otherwise, keys and descriptions refer to plant parts in their mature condition; that is, after they have expanded fully from their embryonic states, excluding any expansion subsequent to that, as happens for example when flower parts (e.g., ovary, sepals) expand in association with fruit set.' added</span>
