    <!-- p. 15 (Symbols +) -->
    <article class="erratum-entry">
        <span class="erratum-date">2013 11 19</span>
        <p><strong>p. 15</strong><br>
        SYMBOLS</p>
        <span class="erratum-detail">+ 1) after a number or range of numbers, it means "or more" (e.g., "6–10+ mm" means "6 to 10 or more mm"); 2) between words (e.g., plant structures, word elements in etymologies) it means "plus" (e.g., "tube + throat 12–16 mm" means that the tube and throat taken together are 12–16 mm). Inserted just below '1', just above '±'</span>
    </article>

