                <p><strong>p. 1444</strong><br>
                ELYMUS<br>
                NOTE: References to number of spikelets per node is best understood as "most, if not all" and best determined by examining nodes in middle of infl. Intergeneric and interspecific hybrids, along with effects of soil moisture on pl growth, render keys even more challenging and frustrating than usual. As treated here, genus incl taxa previously assigned to <em>Agropyron</em> (in part), <em>Elytrigia</em>, <em>Leymus</em>, <em>Pascopyrum</em>, <em>Pseudoroegneria</em>, and <em>Taeniatherum</em>. <em>Elymus &times;aristatus</em> Merr., <em>Elymus arizonicus</em> (Scribn. & J.G. Sm.) Gould, <em>Elymus canadensis</em> L., <em>Elymus interruptus</em> Buckley, <em>Agropyron junceum</em> (L.) P. Beauv. [<em>Thinopyrum junceum</em> (L.) &Aacute;. L&ouml;ve], and <em>Elymus pycnanthus</em> (Godr.) Melderis [<em>Thinopyrum pycnanthum</em> (Godr.) Barkworth] have been reported for CA, may occur sporadically, but do not appear to have become naturalized. Intergeneric hybrids involving <em>Hordeum</em> constitute the genus &times;<em>Elyhordeum</em> and are cited in spp. descriptions. <em>Elymus farctus</em> (Viv.) Melderis subsp. <em>boreo-atlanticus</em> (Simonet & Guin.) Melderis [<em>Elytrigia juncea</em> (L.) Nevski subsp. <em>boreo-atlantica</em> (Simonet & Guin.) Hylander] naturalized, under eradication at Oceano Dunes.</p>
                <span class="erratum-detail">'<em>Elytrigia juncea</em> (L.) Nevski subsp. <em>boreali-atlantica</em> (Simonet & Guin.) Hylander,' deleted (from list of taxa that do not appear to have become naturalized)</span>
                <span class="erratum-detail">'Intergeneric hybrids involving <em>Hordeum</em> constitute the genus &times;<em>Elyhordeum</em>. They are cited in spp. descriptions.' made 'Intergeneric hybrids involving <em>Hordeum</em> constitute the genus &times;<em>Elyhordeum</em> and are cited in spp. descriptions.'</span>
                <span class="erratum-detail">'<em>Elymus farctus</em> (Viv.) Melderis subsp. <em>boreo-atlanticus</em> (Simonet & Guin.) Melderis [<em>Elytrigia juncea</em> (L.) Nevski subsp. <em>boreo-atlantica</em> (Simonet & Guin.) Hylander] naturalized, under eradication at Oceano Dunes.' added</span>
