                <p>DISTRIBUTION OUTSIDE CALIFORNIA: to Alaska, eastern United States, Mexico.<br>
                SYNONYMS: Dodecatheon pulchellum (Raf.) Merr.; Dodecatheon pulchellum var. monanthum (Greene) B. Boivin; Dodecatheon pulchellum var. shoshonense (A. Nelson) Reveal; Dodecatheon pulchellum subsp. monanthum (Greene ex R. Knuth) H.J. Thomps. ex Munz, ined.; Primula pauciflora var. macrocarpa (A. Gray) A.R. Mast & Reveal; Primula pauciflora var. monantha (Greene) A.R. Mast & Reveal; Primula pauciflora var. shoshonensis (A. Nelson) A.R. Mast & Reveal</p>
