                <p>UNABRIDGED NOTE: Highly variable polyploid complex in need of further study. Three varieties recognized for California by Reveal, treated in TJM2 as synonyms pending sufficient genetic, ecological, and geographic evidence, for which there are now combinations in <em>Primula</em>: <em>Primula pauciflora</em> (Greene) A.R. Mast & Reveal var. <em>pauciflora</em>, Lassen Co. to Alaska, North Dakota, Nebraska, MEX; <em>Primula pauciflora</em> var. <em>monantha</em> (Greene) A.R. Mast & Reveal, Del Norte Co. to Washington, also possibly Utah; and <em>Primula pauciflora</em> var. <em>shoshonense</em> (A. Nelson) A.R. Mast & Reveal, Mono and Inyo cos. (including Fish Slough, Owens Valley) to Oregon, Idaho, UT.</p>
